use std::collections::HashSet;
use std::fmt;

// Each name in `derive` asks the compiler to write one standard ability for us.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
struct Version {
    major: u32,
    minor: u32,
}

// Display (the `{}` text for users) cannot be derived: we choose how it looks.
impl fmt::Display for Version {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "v{}.{}", self.major, self.minor)
    }
}

fn main() {
    let a = Version {
        major: 1,
        minor: 10,
    };
    let b = Version { major: 1, minor: 9 };
    println!("display: {a}");
    println!("a == b: {}", a == b);
    println!("a > b: {}", a > b);

    let mut all = vec![a, b, Version::default()];
    all.sort();
    let names: Vec<String> = all.iter().map(|v| v.to_string()).collect();
    println!("sorted: {}", names.join(" "));

    let mut seen = HashSet::new();
    for v in [a, b, Version::default(), a] {
        seen.insert(v);
    }
    println!("distinct: {}", seen.len());
}

go.code:
package main

import (
	"cmp"
	"fmt"
	"slices"
	"strings"
)

// A struct of comparable fields gets == and works as a map key with nothing declared.
type Version struct {
	Major, Minor uint32
}

// Stringer is Go's Display: fmt calls String() for %v and %s.
func (v Version) String() string {
	return fmt.Sprintf("v%d.%d", v.Major, v.Minor)
}

// Ordering is not automatic: write the comparison.
func compare(a, b Version) int {
	if c := cmp.Compare(a.Major, b.Major); c != 0 {
		return c
	}
	return cmp.Compare(a.Minor, b.Minor)
}

func main() {
	a := Version{1, 10}
	b := Version{1, 9}
	fmt.Println("display:", a)
	fmt.Println("a == b:", a == b)
	fmt.Println("a > b:", compare(a, b) > 0)

	all := []Version{a, b, {}}
	slices.SortFunc(all, compare)
	names := []string{}
	for _, v := range all {
		names = append(names, v.String())
	}
	fmt.Println("sorted:", strings.Join(names, " "))

	seen := map[Version]bool{}
	for _, v := range []Version{a, b, {}, a} {
		seen[v] = true
	}
	fmt.Println("distinct:", len(seen))
}

